#!/bin/bash\n\nset -euo pipefail\n\n# Mock rationale: For docker-tools, interacting with the Docker daemon directly in unit tests is slow, non-deterministic, and requires a running Docker environment. Mocking `docker` commands allows for fast, isolated, and reliable testing of the shell script's logic.\n\n# --- Test Utilities ---\n\n# Global variable to store mocked docker commands\nmocked_docker_calls=()\n\n# Function to mock the 'docker' command\ndocker() {\n    local cmd="$1"\n    shift\n    local args=("$@")\n    mocked_docker_calls+=("docker $cmd ${args[*]}")\n\n    case "$cmd" in\n        commit)\n            echo "Mocked docker commit $1 $2"\n            ;;\n        run)\n            echo "Mocked docker run -d --name $2 $3"\n            ;;\n        images)\n            # Mock rationale: Simulates the output of 'docker images --format {{.Repository}}' for deterministic testing.\n            # This output is then filtered by grep in the actual script functions (_load, _delete, _list).\n            if [[ "${args[*]}" == *"--format {{.Repository}}"* ]]; then\n                echo "temporal-echo-snapshot-test-snapshot\ntemporal-echo-snapshot-existing-snapshot\ntemporal-echo-snapshot-another-snapshot\nother-image:latest\nsome-other-image"\n            else\n                echo "Mocked docker images output (general)"\n            fi\n            ;;\n        rmi)\n            echo "Mocked docker rmi $1"\n            ;;\n        *)  # For any other docker command, just acknowledge it\n            echo "Mocked docker $cmd ${args[*]}"\n            ;;\n    esac\n    return 0\n}\n\n# Helper to assert if a command was called\nassert_command_called() {\n    local expected_call="$1"\n    local found=0\n    for call in "${mocked_docker_calls[@]}"; do\n        if [[ "$call" == "$expected_call" ]]; then\n            found=1\n            break\n        fi\n    done\n    if [[ $found -eq 0 ]]; then\n        echo "Test Failed: Expected command '$expected_call' was not called." >&2\n        echo "All calls: ${mocked_docker_calls[*]}" >&2\n        exit 1\n    fi\n}\n\n# Helper to assert output\nassert_output() {\n    local expected="$1"\n    local actual="$2"\n    if [[ "$actual" != "$expected" ]]; then\n        echo "Test Failed: Expected output '\n$expected\n' but got '\n$actual\n'" >&2\n        exit 1\n    fi\n}\n\n# Helper to reset mocks before each test\nreset_mocks() {\n    mocked_docker_calls=()\n}\n\n# --- Tests ---\n\necho "Running tests for temporal_echo.sh..."\n\n# Test 1: help command\nreset_mocks\noutput=$(./src/temporal_echo.sh help)\nif ! echo "$output" | grep -q "Usage: ./src/temporal_echo.sh <command>"; then\n    echo "Test Failed: Help output not as expected." >&2\n    exit 1\nfi\necho "Test 1 Passed: Help command works."
\n# Test 2: save command - success\nreset_mocks\noutput=$(./src/temporal_echo.sh save my-container test-snapshot)\nassert_command_called "docker commit my-container temporal-echo-snapshot-test-snapshot"\nassert_output "Saving temporal echo for container 'my-container' as 'test-snapshot'...\nSnapshot 'test-snapshot' saved successfully." "$output"\necho "Test 2 Passed: Save command works."
\n# Test 3: save command - missing arguments\nreset_mocks\nif output=$(./src/temporal_echo.sh save my-container 2>&1); then\n    echo "Test Failed: Save command with missing args should fail." >&2\n    exit 1\nfi\nif ! echo "$output" | grep -q "Error: Both container_name and snapshot_name are required for 'save'."; then\n    echo "Test Failed: Incorrect error message for missing save args." >&2\n    exit 1\nfi\necho "Test 3 Passed: Save command handles missing arguments."
\n# Test 4: load command - success\nreset_mocks\noutput=$(./src/temporal_echo.sh load existing-snapshot new-app-instance)\nassert_command_called "docker run -d --name new-app-instance temporal-echo-snapshot-existing-snapshot"\nassert_output "Loading temporal echo 'existing-snapshot' into new container 'new-app-instance'...\nContainer 'new-app-instance' created and running from snapshot 'existing-snapshot'." "$output"\necho "Test 4 Passed: Load command works."
\n# Test 5: load command - snapshot not found\nreset_mocks\nif output=$(./src/temporal_echo.sh load non-existent-snapshot another-app 2>&1); then\n    echo "Test Failed: Load command with non-existent snapshot should fail." >&2\n    exit 1\nfi\nif ! echo "$output" | grep -q "Error: Snapshot 'non-existent-snapshot' not found."; then\n    echo "Test Failed: Incorrect error message for non-existent snapshot." >&2\n    exit 1\nfi\necho "Test 5 Passed: Load command handles non-existent snapshot."
\n# Test 6: list command\nreset_mocks\noutput=$(./src/temporal_echo.sh list)\nassert_output "Available Temporal Echoes (Snapshots):\n  test-snapshot\n  existing-snapshot\n  another-snapshot" "$output" # Based on mocked docker images output\necho "Test 6 Passed: List command works."
\n# Test 7: delete command - success\nreset_mocks\noutput=$(./src/temporal_echo.sh delete existing-snapshot)\nassert_command_called "docker rmi temporal-echo-snapshot-existing-snapshot"\nassert_output "Deleting temporal echo 'existing-snapshot'...\nSnapshot 'existing-snapshot' deleted successfully." "$output"\necho "Test 7 Passed: Delete command works."
\n# Test 8: delete command - snapshot not found\nreset_mocks\nif output=$(./src/temporal_echo.sh delete non-existent-snapshot 2>&1); then\n    echo "Test Failed: Delete command with non-existent snapshot should fail." >&2\n    exit 1\nfi\nif ! echo "$output" | grep -q "Error: Snapshot 'non-existent-snapshot' not found."; then\n    echo "Test Failed: Incorrect error message for non-existent snapshot deletion." >&2\n    exit 1\nfi\necho "Test 8 Passed: Delete command handles non-existent snapshot."
\n# Test 9: unknown command\nreset_mocks\noutput=$(./src/temporal_echo.sh unknown-command)\nif ! echo "$output" | grep -q "Usage: ./src/temporal_echo.sh <command>"; then\n    echo "Test Failed: Unknown command should show help." >&2\n    exit 1\nfi\necho "Test 9 Passed: Unknown command defaults to help."
\n\necho "All tests passed!"
